import os
import json
import numpy as np
from PIL import Image
from collections import defaultdict

INPUT_DIR = "/tmp_workspace/input"
RESULTS_DIR = "/tmp_workspace/results"

pieces = {}
for i in range(1, 38):
    fname = f"piece_{i:02d}.png"
    path = os.path.join(INPUT_DIR, fname)
    img = Image.open(path).convert("RGB")
    pieces[fname] = np.array(img)

print(f"Loaded {len(pieces)} pieces, shape: {pieces['piece_01.png'].shape}")

# Compute edge features: RGB along each edge (top, right, bottom, left)
def get_edges(arr):
    top = arr[0, :, :].astype(np.float32)
    right = arr[:, -1, :].astype(np.float32)
    bottom = arr[-1, :, :].astype(np.float32)
    left = arr[:, 0, :].astype(np.float32)
    return top, right, bottom, left

# For each piece, store edges for all 4 rotations (0, 90, 180, 270 clockwise)
piece_rot_edges = {}
for fname, arr in pieces.items():
    rots = []
    for k in range(4):
        if k == 0:
            rot_arr = arr
        elif k == 1:
            rot_arr = np.rot90(arr, k=3, axes=(0,1))
        elif k == 2:
            rot_arr = np.rot90(arr, k=2, axes=(0,1))
        elif k == 3:
            rot_arr = np.rot90(arr, k=1, axes=(0,1))
        edges = get_edges(rot_arr)
        rots.append(edges)
    piece_rot_edges[fname] = rots

# Edge compatibility: MSE between edges
def edge_mse(e1, e2):
    return np.mean((e1 - e2)**2)

fnames = list(pieces.keys())

# Precompute pairwise match costs
match_cost = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(float))))
for fa in fnames:
    for fb in fnames:
        if fa == fb: continue
        for ra in range(4):
            for rb in range(4):
                right_a = piece_rot_edges[fa][ra][1]
                left_b = piece_rot_edges[fb][rb][3]
                mse = edge_mse(right_a, left_b)
                match_cost[fa][ra][fb][rb] = mse

match_cost_tb = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(float))))
for fa in fnames:
    for fb in fnames:
        if fa == fb: continue
        for ra in range(4):
            for rb in range(4):
                bottom_a = piece_rot_edges[fa][ra][2]
                top_b = piece_rot_edges[fb][rb][0]
                mse = edge_mse(bottom_a, top_b)
                match_cost_tb[fa][ra][fb][rb] = mse

all_rl = []
for fa in fnames:
    for fb in fnames:
        if fa == fb: continue
        for ra in range(4):
            for rb in range(4):
                all_rl.append(match_cost[fa][ra][fb][rb])
all_rl = np.array(all_rl)
print(f"Right-Left MSE stats: min={all_rl.min():.2f}, mean={all_rl.mean():.2f}, median={np.median(all_rl):.2f}")

# Find best threshold using gap analysis
vals = sorted(all_rl)
# Look for a natural gap in the distribution
for i in range(1, len(vals)):
    if vals[i] > vals[i-1] * 3 and vals[i] > 50:
        threshold_guess = vals[i]
        print(f"Potential gap at MSE={threshold_guess:.2f} (index {i})")
        break
else:
    threshold_guess = 200

# Compute best match stats per piece to identify distractors
edge_best_match = {}
for fname in fnames:
    for rot in range(4):
        best_r = min(match_cost[fname][rot][fb][rb] for fb in fnames if fb != fname for rb in range(4))
        best_b = min(match_cost_tb[fname][rot][fb][rb] for fb in fnames if fb != fname for rb in range(4))
        best_t = min(match_cost_tb[fb][rb][fname][rot] for fb in fnames if fb != fname for rb in range(4))
        best_l = min(match_cost[fb][rb][fname][rot] for fb in fnames if fb != fname for rb in range(4))
        edge_best_match[(fname, rot)] = (best_t, best_r, best_b, best_l)

# Score pieces by number of good edges (potential neighbors in grid)
good_threshold = 300
piece_scores = {}
for fname in fnames:
    scores = []
    for rot in range(4):
        t, r, b, l = edge_best_match[(fname, rot)]
        good_count = sum(1 for v in [t, r, b, l] if v < good_threshold)
        scores.append((good_count, rot, (t, r, b, l)))
    scores.sort(reverse=True)
    piece_scores[fname] = scores

sorted_pieces = sorted(fnames, key=lambda f: piece_scores[f][0][0], reverse=True)
print(f"Top 25 pieces by good edge count: {sorted_pieces[:25]}")
print(f"Bottom 12 pieces (distractors): {sorted_pieces[25:]}")

selected = set(sorted_pieces[:25])
distractors = sorted_pieces[25:]

# Try to assemble grid
def solve_grid_selected(threshold):
    grid = [[None for _ in range(5)] for _ in range(5)]
    used = set()

    def get_candidates(r, c):
        candidates = []
        for fname in selected:
            if fname in used: continue
            for rot in range(4):
                ok = True
                if c > 0 and grid[r][c-1] is not None:
                    nf, nr = grid[r][c-1]
                    if match_cost[nf][nr][fname][rot] > threshold:
                        ok = False
                if ok and r > 0 and grid[r-1][c] is not None:
                    nf, nr = grid[r-1][c]
                    if match_cost_tb[nf][nr][fname][rot] > threshold:
                        ok = False
                if ok:
                    candidates.append((fname, rot))
        return candidates

    def select_next_cell():
        best_cell = None
        best_count = float('inf')
        for r in range(5):
            for c in range(5):
                if grid[r][c] is None:
                    count = len(get_candidates(r, c))
                    if count < best_count:
                        best_count = count
                        best_cell = (r, c)
        return best_cell, best_count

    def backtrack():
        cell, count = select_next_cell()
        if cell is None: return True
        if count == 0: return False
        r, c = cell
        candidates = get_candidates(r, c)
        def score(cand):
            fname, rot = cand
            s = 0
            if c > 0 and grid[r][c-1] is not None:
                nf, nr = grid[r][c-1]
                s += match_cost[nf][nr][fname][rot]
            if r > 0 and grid[r-1][c] is not None:
                nf, nr = grid[r-1][c]
                s += match_cost_tb[nf][nr][fname][rot]
            return s
        candidates.sort(key=score)

        for fname, rot in candidates:
            grid[r][c] = (fname, rot)
            used.add(fname)
            if backtrack(): return True
            grid[r][c] = None
            used.remove(fname)
        return False

    if backtrack():
        return grid
    return None

grid = None
for thresh in [50, 100, 150, 200, 300, 500, 800, 1000, 1500, 2000, 3000, 5000]:
    grid = solve_grid_selected(thresh)
    if grid is not None:
        print(f"Selected solver succeeded with threshold={thresh}")
        break
    print(f"Selected solver failed with threshold={thresh}")

# If still no grid, try greedy approach
if grid is None:
    print("Trying greedy approach...")
    best_grid = None
    best_score = float('inf')

    for start_fname in selected:
        for start_rot in range(4):
            g = [[None for _ in range(5)] for _ in range(5)]
            used = set()
            g[0][0] = (start_fname, start_rot)
            used.add(start_fname)

            failed = False
            for r in range(5):
                for c in range(5):
                    if r == 0 and c == 0: continue
                    best_cand = None
                    best_mse = float('inf')
                    for fname in selected:
                        if fname in used: continue
                        for rot in range(4):
                            ok = True
                            score = 0
                            if c > 0 and g[r][c-1] is not None:
                                nf, nr = g[r][c-1]
                                mse = match_cost[nf][nr][fname][rot]
                                if mse > 5000: ok = False
                                score += mse
                            if r > 0 and g[r-1][c] is not None:
                                nf, nr = g[r-1][c]
                                mse = match_cost_tb[nf][nr][fname][rot]
                                if mse > 5000: ok = False
                                score += mse
                            if ok and score < best_mse:
                                best_mse = score
                                best_cand = (fname, rot)
                    if best_cand is None:
                        failed = True
                        break
                    g[r][c] = best_cand
                    used.add(best_cand[0])
                if failed: break

            if not failed:
                total = 0
                for r in range(5):
                    for c in range(5):
                        if c < 4:
                            nf, nr = g[r][c]
                            fn, rt = g[r][c+1]
                            total += match_cost[nf][nr][fn][rt]
                        if r < 4:
                            nf, nr = g[r][c]
                            fn, rt = g[r+1][c]
                            total += match_cost_tb[nf][nr][fn][rt]
                if total < best_score:
                    best_score = total
                    best_grid = g
                    print(f"Found grid starting {start_fname} rot{start_rot}, score={total:.2f}")

    grid = best_grid

if grid is None:
    print("ERROR: Could not assemble grid")
    exit(1)

# Assemble image
assembled = np.zeros((600, 600, 3), dtype=np.uint8)
for r in range(5):
    for c in range(5):
        fname, rot = grid[r][c]
        arr = pieces[fname]
        if rot == 0:
            rot_arr = arr
        elif rot == 1:
            rot_arr = np.rot90(arr, k=3, axes=(0,1))
        elif rot == 2:
            rot_arr = np.rot90(arr, k=2, axes=(0,1))
        elif rot == 3:
            rot_arr = np.rot90(arr, k=1, axes=(0,1))
        assembled[r*120:(r+1)*120, c*120:(c+1)*120, :] = rot_arr

img = Image.fromarray(assembled)
img.save(os.path.join(RESULTS_DIR, "assembled.png"))
print("Saved assembled.png")

# Prepare result
grid_names = [[None for _ in range(5)] for _ in range(5)]
transforms = {}
used_names = set()
for r in range(5):
    for c in range(5):
        fname, rot = grid[r][c]
        grid_names[r][c] = fname
        used_names.add(fname)
        if rot != 0:
            if rot == 1:
                transforms[fname] = "rotate_90"
            elif rot == 2:
                transforms[fname] = "rotate_180"
            elif rot == 3:
                transforms[fname] = "rotate_270"

# Verify all 25 selected pieces are used
assert len(used_names) == 25

# Use OpenRouter API to describe the image
import requests
import base64
from io import BytesIO

buffer = BytesIO()
img.save(buffer, format="PNG")
img_b64 = base64.b64encode(buffer.getvalue()).decode()

api_key = os.environ.get("OPENROUTER_API_KEY")
base_url = os.environ.get("OPENROUTER_BASE_URL", "https://openrouter.ai/api/v1")

description = "一张拼接好的图片"
if api_key:
    try:
        response = requests.post(
            f"{base_url}/chat/completions",
            headers={"Authorization": f"Bearer {api_key}", "Content-Type": "application/json"},
            json={
                "model": "anthropic/claude-3.5-sonnet",
                "messages": [
                    {"role": "user", "content": [
                        {"type": "text", "text": "请用中文描述这张图片的内容。简要描述即可。"},
                        {"type": "image_url", "image_url": {"url": f"data:image/png;base64,{img_b64}"}}
                    ]}
                ]
            },
            timeout=30
        )
        if response.status_code == 200:
            description = response.json()["choices"][0]["message"]["content"]
            print(f"API description: {description}")
        else:
            print(f"API error: {response.status_code}")
    except Exception as e:
        print(f"API exception: {e}")

result = {
    "grid": grid_names,
    "transforms": transforms,
    "distractors": distractors,
    "description": description
}

with open(os.path.join(RESULTS_DIR, "result.json"), "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

print("Saved result.json")
print(f"Grid: {grid_names}")
print(f"Transforms: {transforms}")
print(f"Distractors: {distractors}")

