print(f"Top-Bottom MSE stats: min={all_mse_tb.min():.2f}, max={all_mse_tb.max():.2f}, mean={all_mse_tb.mean():.2f}, median={np.median(all_mse_tb):.2f}")

# Sort and look for gaps
