fnames = list(pieces.keys())

def edge_mse(e1, e2):
    return np.mean((e1 - e2)**2)

# Precompute MSE for all pairs and rotations
match_mse = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(float))))
match_mse_tb = defaultdict(lambda: defaultdict(lambda: defaultdict(lambda: defaultdict(float))))

for fa in fnames:
    for fb in fnames:
        if fa == fb: continue
        for ra in range(4):
            for rb in range(4):
                arr_a = pieces[fa]
                if ra == 1: arr_a = np.rot90(arr_a, k=3, axes=(0,1))
                elif ra == 2: arr_a = np.rot90(arr_a, k=2, axes=(0,1))
                elif ra == 3: arr_a = np.rot90(arr_a, k=1, axes=(0,1))

                arr_b = pieces[fb]
                if rb == 1: arr_b = np.rot90(arr_b, k=3, axes=(0,1))
                elif rb == 2: arr_b = np.rot90(arr_b, k=2, axes=(0,1))
                elif rb == 3: arr_b = np.rot90(arr_b, k=1, axes=(0,1))

                right_a = arr_a[:, -1, :].astype(np.float32)
                left_b = arr_b[:, 0, :].astype(np.float32)
                mse = edge_mse(right_a, left_b)
                match_mse[fa][ra][fb][rb] = mse

                bottom_a = arr_a[-1, :, :].astype(np.float32)
                top_b = arr_b[0, :, :].astype(np.float32)
                mse = edge_mse(bottom_a, top_b)
                match_mse_tb[fa][ra][fb][rb] = mse

# Identify distractors by best edge match quality
edge_best_mse = {}
for fname in fnames:
    for rot in range(4):
        best_r = min(match_mse[fname][rot][fb][rb] for fb in fnames if fb != fname for rb in range(4))
        best_b = min(match_mse_tb[fname][rot][fb][rb] for fb in fnames if fb != fname for rb in range(4))
        best_t = min(match_mse_tb[fb][rb][fname][rot] for fb in fnames if fb != fname for rb in range(4))
        best_l = min(match_mse[fb][rb][fname][rot] for fb in fnames if fb != fname for rb in range(4))
        edge_best_mse[(fname, rot)] = (best_t, best_r, best_b, best_l)

# Score pieces by number of good edges (low MSE = good match)
good_mse_threshold = 2000
piece_scores = {}
for fname in fnames:
    scores = []
    for rot in range(4):
        t, r, b, l = edge_best_mse[(fname, rot)]
        good_count = sum(1 for v in [t, r, b, l] if v < good_mse_threshold)
        scores.append((good_count, rot, (t, r, b, l)))
    scores.sort(reverse=True)
    piece_scores[fname] = scores

sorted_pieces = sorted(fnames, key=lambda f: piece_scores[f][0][0], reverse=True)
print(f"Top 25 pieces by good edge count: {sorted_pieces[:25]}")
print(f"Bottom 12 pieces (distractors): {sorted_pieces[25:]}")

selected = set(sorted_pieces[:25])
distractors = sorted_pieces[25:]

# Solve with strict MSE threshold
def solve_grid_mse(threshold):
    grid = [[None for _ in range(5)] for _ in range(5)]
    used = set()

    def get_candidates(r, c):
        candidates = []
        for fname in selected:
            if fname in used: continue
            for rot in range(4):
                ok = True
                if c > 0 and grid[r][c-1] is not None:
                    nf, nr = grid[r][c-1]
                    if match_mse[nf][nr][fname][rot] > threshold:
                        ok = False
                if ok and r > 0 and grid[r-1][c] is not None:
                    nf, nr = grid[r-1][c]
                    if match_mse_tb[nf][nr][fname][rot] > threshold:
                        ok = False
                if ok:
                    candidates.append((fname, rot))
        return candidates

    def select_next_cell():
        best_cell = None
        best_count = float('inf')
        for r in range(5):
            for c in range(5):
                if grid[r][c] is None:
                    count = len(get_candidates(r, c))
                    if count < best_count:
                        best_count = count
                        best_cell = (r, c)
        return best_cell, best_count

    def backtrack():
        cell, count = select_next_cell()
        if cell is None: return True
        if count == 0: return False
        r, c = cell
        candidates = get_candidates(r, c)
        def score(cand):
            fname, rot = cand
            s = 0
            if c > 0 and grid[r][c-1] is not None:
                nf, nr = grid[r][c-1]
                s += match_mse[nf][nr][fname][rot]
            if r > 0 and grid[r-1][c] is not None:
                nf, nr = grid[r-1][c]
                s += match_mse_tb[nf][nr][fname][rot]
            return s
        candidates.sort(key=score)

        for fname, rot in candidates:
            grid[r][c] = (fname, rot)
            used.add(fname)
            if backtrack(): return True
            grid[r][c] = None
            used.remove(fname)
        return False

    if backtrack():
        return grid
    return None

grid = None
for thresh in [500, 600, 700, 800, 900, 1000, 1200, 1500, 2000, 2500, 3000, 4000, 5000]:
    grid = solve_grid_mse(thresh)
    if grid is not None:
        print(f"MSE solver succeeded with threshold={thresh}")
        break
    print(f"MSE solver failed with threshold={thresh}")

if grid is None:
    print("ERROR: Could not assemble grid")
    exit(1)

# Assemble image
assembled = np.zeros((600, 600, 3), dtype=np.uint8)
for r in range(5):
