print("Saved result.json")
print(f"Number of rotated pieces: {len(transforms)}")
print(f"Grid: {grid_names}")
print(f"Transforms: {transforms}")
print(f"Distractors: {distractors}")

# Verify boundary MSE
total_mse = 0
boundary_count = 0
for r in range(5):
    for c in range(5):
        fname, rot = grid[r][c]
        if c < 4:
            fname_right, rot_right = grid[r][c+1]
            mse = match_mse[fname][rot][fname_right][rot_right]
            total_mse += mse
            boundary_count += 1
        if r < 4:
            fname_bottom, rot_bottom = grid[r+1][c]
            mse = match_mse_tb[fname][rot][fname_bottom][rot_bottom]
            total_mse += mse
            boundary_count += 1

print(f"\nAverage boundary MSE: {total_mse / boundary_count:.2f}")
print(f"Total boundary MSE: {total_mse:.2f}")

