# Find all good matches (MSE < 3000)
threshold = 3000
good_matches = []
for fa in fnames:
    for fb in fnames:
        if fa == fb: continue
        for ra in range(4):
            for rb in range(4):
                if match_mse[fa][ra][fb][rb] < threshold:
                    good_matches.append((match_mse[fa][ra][fb][rb], fa, ra, fb, rb, 'rl'))
                if match_mse_tb[fa][ra][fb][rb] < threshold:
                    good_matches.append((match_mse_tb[fa][ra][fb][rb], fa, ra, fb, rb, 'tb'))

good_matches.sort()

# Build adjacency list
adj = defaultdict(list)
for mse, fa, ra, fb, rb, direction in good_matches:
    adj[(fa, ra)].append((fb, rb, mse, direction))

# Count good matches per piece
piece_match_count = defaultdict(int)
for mse, fa, ra, fb, rb, direction in good_matches:
    piece_match_count[fa] += 1

# Select top 25 pieces by match count
sorted_pieces = sorted(fnames, key=lambda f: piece_match_count[f], reverse=True)
selected = set(sorted_pieces[:25])
distractors = sorted_pieces[25:]

print(f"Top 25 pieces by match count: {sorted_pieces[:25]}")
print(f"Bottom 12 pieces (distractors): {distractors}")

# Try to build grid using backtracking with good matches
# Use a more flexible approach: allow some boundaries to have higher MSE

def solve_grid_flexible(max_mse):
    grid = [[None for _ in range(5)] for _ in range(5)]
    used = set()

    def get_candidates(r, c):
        candidates = []
        for fname in selected:
            if fname in used: continue
            for rot in range(4):
                ok = True
                score = 0

                # Check left neighbor
                if c > 0 and grid[r][c-1] is not None:
                    nf, nr = grid[r][c-1]
                    mse = match_mse[nf][nr][fname][rot]
                    if mse > max_mse:
                        ok = False
                    score += mse

                # Check top neighbor
                if ok and r > 0 and grid[r-1][c] is not None:
                    nf, nr = grid[r-1][c]
                    mse = match_mse_tb[nf][nr][fname][rot]
                    if mse > max_mse:
                        ok = False
                    score += mse

                if ok:
                    candidates.append((score, fname, rot))

        return candidates

    def select_next_cell():
        best_cell = None
        best_count = float('inf')
        for r in range(5):
            for c in range(5):
                if grid[r][c] is None:
                    count = len(get_candidates(r, c))
                    if count < best_count:
                        best_count = count
                        best_cell = (r, c)
        return best_cell, best_count

    def backtrack():
        cell, count = select_next_cell()
        if cell is None: return True
        if count == 0: return False
        r, c = cell
        candidates = get_candidates(r, c)
        candidates.sort()

        for score, fname, rot in candidates:
            grid[r][c] = fname
            used.add(fname)
            if backtrack(): return True
            grid[r][c] = None
            used.remove(fname)
        return False

    if backtrack():
        return grid
    return None

# Try different max MSE values
grid = None
for max_mse in [2000, 2500, 3000, 3500, 4000, 4500, 5000, 6000, 7000, 8000, 9000, 10000]:
    grid = solve_grid_flexible(max_mse)
    if grid is not None:
        print(f"Flexible solver succeeded with max_mse={max_mse}")
        break
    print(f"Flexible solver failed with max_mse={max_mse}")

if grid is None:
    print("ERROR: Could not assemble grid")
    exit(1)

# Determine rotations from the grid
# For each piece, try all rotations and pick the one that minimizes boundary MSE
rotations = {}
for r in range(5):
    for c in range(5):
        fname = grid[r][c]
        best_rot = 0
        best_score = float('inf')
        for rot in range(4):
            score = 0
            if c > 0:
                nf = grid[r][c-1]
                nr = rotations[nf]
                score += match_mse[nf][nr][fname][rot]
            if r > 0:
                nf = grid[r-1][c]
                nr = rotations[nf]
                score += match_mse_tb[nf][nr][fname][rot]
            if score < best_score:
                best_score = score
                best_rot = rot
        rotations[fname] = best_rot

# Assemble image
assembled = np.zeros((600, 600, 3), dtype=np.uint8)
for r in range(5):
    for c in range(5):
        fname = grid[r][c]
        rot = rotations[fname]
        arr = pieces[fname]
        if rot == 0:
            rot_arr = arr
        elif rot == 1:
            rot_arr = np.rot90(arr, k=3, axes=(0,1))
        elif rot == 2:
            rot_arr = np.rot90(arr, k=2, axes=(0,1))
        elif rot == 3:
            rot_arr = np.rot90(arr, k=1, axes=(0,1))
        assembled[r*120:(r+1)*120, c*120:(c+1)*120, :] = rot_arr

img = Image.fromarray(assembled)
img.save(os.path.join(RESULTS_DIR, "assembled.png"))
print("Saved assembled.png")

# Prepare result
grid_names = [[grid[r][c] for c in range(5)] for r in range(5)]
transforms = {}
for fname, rot in rotations.items():
    if rot != 0:
        if rot == 1:
            transforms[fname] = "rotate_90"
        elif rot == 2:
            transforms[fname] = "rotate_180"
        elif rot == 3:
            transforms[fname] = "rotate_270"

result = {
    "grid": grid_names,
    "transforms": transforms,
    "distractors": distractors,
    "description": "一张拼接好的图片"
}

with open(os.path.join(RESULTS_DIR, "result.json"), "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

print("Saved result.json")
print(f"Number of rotated pieces: {len(transforms)}")
print(f"Grid: {grid_names}")
print(f"Transforms: {transforms}")
print(f"Distractors: {distractors}")

# Verify boundary MSE
total_mse = 0
boundary_count = 0
for r in range(5):
    for c in range(5):
        fname = grid[r][c]
        rot = rotations[fname]
        if c < 4:
            fname_right = grid[r][c+1]
            rot_right = rotations[fname_right]
            mse = match_mse[fname][rot][fname_right][rot_right]
            total_mse += mse
            boundary_count += 1
        if r < 4:
            fname_bottom = grid[r+1][c]
            rot_bottom = rotations[fname_bottom]
            mse = match_mse_tb[fname][rot][fname_bottom][rot_bottom]
            total_mse += mse
            boundary_count += 1

print(f"\nAverage boundary MSE: {total_mse / boundary_count:.2f}")
print(f"Total boundary MSE: {total_mse:.2f}")

